/** @param {string} path */
declare function directorySizeBytes(path: string): Promise<any>;
/** @param {string} path */
declare function filesystemUsage(path: string): {
    path: string;
    totalBytes: number;
    freeBytes: number;
    usedBytes: number;
    usedPercent: number;
} | null;

export { directorySizeBytes, filesystemUsage };
